def fuse_votes(rows,weights,constant=60,k=3):
    if type(k) is not int or not 1<=k<=256:
        raise ValueError("k in [1,256] required")
    weights=fusion_weights(list(weights.items())) if isinstance(weights,dict) else {}
    validate_votes(rows,weights)
    rrf_vote(1,constant,1)
    scores={}
    contributors={}
    for row in rows:
        identity=row['id']
        scores.setdefault(identity,[]).append(rrf_vote(row['rank'],constant,weights[row['retriever']]))
        contributors.setdefault(identity,[]).append({'retriever':row['retriever'],'rank':row['rank'],'raw_score':row['raw_score']})
    try:
        totals={key:math.fsum(values) for key,values in scores.items()}
    except (OverflowError,ValueError) as exc:
        raise ValueError("fusion overflow") from exc
    if any(not math.isfinite(x) for x in totals.values()):
        raise ValueError("non-finite fused score")
    ordered=sorted(totals,key=lambda key:(-totals[key],key))[:k]
    return [{'id':key,'score':totals[key],'rank':rank,'contributors':sorted(contributors[key],key=lambda c:c['retriever'])} for rank,key in enumerate(ordered,1)]

