def resolve_evidence(eligible,support):
    by_key={row['evidence_key']:row for row in eligible}
    if len(by_key)!=len(eligible):
        raise ValueError("ambiguous evidence keys")
    gold=set()
    for key,atoms in support.items():
        if key not in by_key or not isinstance(atoms,list) or not atoms:
            raise ValueError("invalid evidence label")
        text=by_key[key]['text'].casefold()
