import json,hashlib
def corpus_digest(rows):
    if len({r['chunk_id'] for r in rows})!=len(rows):
        raise ValueError("duplicate chunk IDs")
    records=[]
    for row in sorted(rows,key=lambda r:r['chunk_id']):
        metadata=row['metadata']
        if len({k for k,v in metadata})!=len(metadata):
            raise ValueError("duplicate metadata keys")
        records.append({**row,'metadata':sorted(metadata)})
    payload=json.dumps(records,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()
